// ===========================================================================================================
// libphext-cs: The Fourth Root - Chain Fixture Conformance Tests
// Consumes the shared libphext 0.6 chain fixtures in tests/fixtures/chains/
// (see FIXTURES.md in the ports program workspace; format
// "libphext-0.6-chain-fixtures/1", generated by libphext-rs 0.6.0 itself).
//
// For every case: parse the input with ParseChains, check the chain / member /
// scroll structure recorded in the per-case manifest.json (byte lengths and
// SHA-256 hashes, generated by calling the reference library), check every
// recorded fetch against Chain.Fetch (result bytes and the manifest `found`
// flag), and require SerializeChains(ParseChains(input)) to be byte-identical
// to the input.
// ===========================================================================================================

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Xunit;
using Phext;

namespace Phext.Tests;

public class ChainFixtureTests
{
    private static string FixturesRoot =>
        Path.Combine(AppContext.BaseDirectory, "fixtures", "chains");

    private static string Sha256Hex(byte[] bytes) =>
        Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();

    public static IEnumerable<object[]> Cases()
    {
        string[] names =
        {
            "single-member",
            "multi-member-3",
            "unclosed-at-eof",
            "adjacent-chain-closes",
            "empty-member",
            "chain-of-one-empty-phext",
            "empty-stream",
            "multiple-chains",
            "real-corpora-chain",
            "multiverse-addressing",
        };
        foreach (var name in names) yield return new object[] { name };
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void ChainFixtureConforms(string caseName)
    {
        string dir = Path.Combine(FixturesRoot, caseName);
        Assert.True(Directory.Exists(dir), $"fixture dir missing: {dir}");

        byte[] inputBytes = File.ReadAllBytes(Path.Combine(dir, "input.phext"));
        using var manifestDoc = JsonDocument.Parse(
            File.ReadAllText(Path.Combine(dir, "manifest.json")));
        JsonElement manifest = manifestDoc.RootElement;

        // 1. Input identity (catches newline-translating reads immediately).
        Assert.Equal(manifest.GetProperty("input_bytes").GetInt32(), inputBytes.Length);
        Assert.Equal(manifest.GetProperty("input_sha256").GetString(), Sha256Hex(inputBytes));

        string input = Encoding.UTF8.GetString(inputBytes);
        var chains = PhextEngine.ParseChains(input);

        // 2. Structure: chains, closed flags, members (bytes + sha256), scrolls
        //    (coordinate, byte length, sha256 of the scroll text).
        JsonElement expectedChains = manifest.GetProperty("chains");
        Assert.Equal(expectedChains.GetArrayLength(), chains.Count);
        int ci = 0;
        foreach (JsonElement expectedChain in expectedChains.EnumerateArray())
        {
            Chain chain = chains[ci];
            Assert.True(
                expectedChain.GetProperty("closed").GetBoolean() == chain.Closed,
                $"{caseName}: chain {ci} closed flag");
            JsonElement expectedMembers = expectedChain.GetProperty("members");
            Assert.Equal(expectedMembers.GetArrayLength(), chain.Members.Count);
            int mi = 0;
            foreach (JsonElement expectedMember in expectedMembers.EnumerateArray())
            {
                string member = chain.Members[mi];
                byte[] memberBytes = Encoding.UTF8.GetBytes(member);
                Assert.Equal(expectedMember.GetProperty("bytes").GetInt32(), memberBytes.Length);
                Assert.Equal(expectedMember.GetProperty("sha256").GetString(), Sha256Hex(memberBytes));

                var scrolls = PhextEngine.Phokenize(member);
                JsonElement expectedScrolls = expectedMember.GetProperty("scrolls");
                Assert.True(
                    expectedScrolls.GetArrayLength() == scrolls.Count,
                    $"{caseName}: member {ci}/{mi} scroll count {scrolls.Count} != {expectedScrolls.GetArrayLength()}");
                int si = 0;
                foreach (JsonElement expectedScroll in expectedScrolls.EnumerateArray())
                {
                    byte[] scrollBytes = Encoding.UTF8.GetBytes(scrolls[si].Scroll);
                    Assert.Equal(expectedScroll.GetProperty("c").GetString(), scrolls[si].Coord.ToString());
                    Assert.Equal(expectedScroll.GetProperty("b").GetInt32(), scrollBytes.Length);
                    Assert.Equal(expectedScroll.GetProperty("s").GetString(), Sha256Hex(scrollBytes));
                    si++;
                }
                mi++;
            }
            ci++;
        }

        // 3. Round-trip: byte-identical re-serialization, no exceptions.
        byte[] roundTripped = Encoding.UTF8.GetBytes(PhextEngine.SerializeChains(chains));
        Assert.Equal(inputBytes, roundTripped);

        // 4. Fetches: result bytes byte-exact vs fetches/NN.txt, and the
        //    manifest `found` flag matches whether the coordinate appears in
        //    Phokenize(addressed member) — the distinction between a miss and
        //    a present-but-empty scroll.
        foreach (JsonElement fetch in manifest.GetProperty("fetches").EnumerateArray())
        {
            int chainIndex = fetch.GetProperty("chain_index").GetInt32();
            string address = fetch.GetProperty("address").GetString()!;
            string expectedFile = fetch.GetProperty("expected_file").GetString()!;
            byte[] expectedBytes = File.ReadAllBytes(Path.Combine(dir, expectedFile));

            string result = chains[chainIndex].Fetch(address);
            Assert.Equal(expectedBytes, Encoding.UTF8.GetBytes(result));

            var parsed = PhextEngine.ParseUniverseAddress(address);
            Assert.NotNull(parsed);
            bool found = false;
            if (parsed.Value.Universe >= 1 && parsed.Value.Universe <= chains[chainIndex].Members.Count)
            {
                string member = chains[chainIndex].Members[parsed.Value.Universe - 1];
                found = PhextEngine.Phokenize(member).Any(p => p.Coord == parsed.Value.Coordinate);
            }
            Assert.True(
                fetch.GetProperty("found").GetBoolean() == found,
                $"{caseName}: fetch {address} found flag (manifest {fetch.GetProperty("found").GetBoolean()}, computed {found})");
        }
    }
}
